// ClaimContextInjection records that Entire's model-facing context injection
// has been emitted for a session, so the injection happens at most once per
// session. First-writer-wins, mirroring ClaimSessionStartBanner (and cleaned up
// by ClearSessionState, which removes every "<sessionID>." file).
//
// Returns (claimed=true) when this call won the race and the caller should emit
// the injection; (claimed=false) when an earlier call already claimed it.
func ClaimContextInjection(ctx context.Context, sessionID string) (claimed bool, err error) {
	if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
		return false, fmt.Errorf("invalid session ID: %w", vErr)
	}

	root, rErr := openSessionStateRoot(ctx)
	if rErr != nil {
		return false, rErr
	}
	defer root.Close()

	f, oErr := root.OpenFile(sessionID+".injected", os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
	if oErr != nil {
		if errors.Is(oErr, os.ErrExist) {
			return false, nil
		}
		return false, fmt.Errorf("failed to create injection marker file: %w", oErr)
	}
	_ = f.Close()
	return true, nil
}

// LoadAgentTypeHint reads the agent type hint written by SessionStart.

// Compile-time assertion that Pi can inject context into the model.
var _ agent.ContextInjector = (*PiAgent)(nil)

// InjectionEvent reports that Pi injects model context at TurnStart
// (before_agent_start) — the only Pi event where the embedded extension can
// return a message that Pi stores in the session and sends to the LLM.
func (a *PiAgent) InjectionEvent() agent.EventType { return agent.TurnStart }

// RenderContextInjection emits a {"inject_context":"..."} envelope on stdout.
// The embedded extension (entire_extension.ts) reads it from the
// before_agent_start hook's stdout and returns it to Pi as a hidden persistent
// message. An empty Text renders nothing.
func (a *PiAgent) RenderContextInjection(inj agent.ContextInjection) ([]byte, error) {
	if strings.TrimSpace(inj.Text) == "" {
		return nil, nil
	}
	b, err := json.Marshal(struct {
		InjectContext string `json:"inject_context"`
	}{InjectContext: inj.Text})
	if err != nil {
		return nil, fmt.Errorf("marshal pi context injection: %w", err)
	}
	return append(b, '\n'), nil
}

// piHookPayload is the JSON the embedded TypeScript extension pipes to
// `entire hooks pi <event>` on stdin.

// entireTrailContextInjection is the one-time, model-facing pointer Entire
// injects so the agent learns that trails exist for this repo. Kept terse: it
// costs context-window tokens on the first turn of every session.
func entireTrailContextInjection() string {
	return "This repository uses Entire. The current branch may have a \"trail\" — a work item that tracks the why/what of the change. Run `entire trail` to view it, or `entire trail --help` for subcommands (list, create, update, watch). Pass `--json` for machine-readable output."
}

// emitContextInjection writes ag's native context-injection payload to stdout
// when ag injects at event.Type and this session has not been injected yet.
// Best-effort: an injection failure never fails the hook.
func emitContextInjection(ctx context.Context, ag agent.Agent, event *agent.Event) {
	injector, ok := agent.AsContextInjector(ag)
	if !ok || injector.InjectionEvent() != event.Type || event.SessionID == "" {
		return
	}
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	claimed, err := strategy.ClaimContextInjection(ctx, event.SessionID)
	if err != nil {
		logging.Warn(logCtx, "failed to claim context injection marker",
			slog.String("error", err.Error()))
		return
	}
	if !claimed {
		return // already injected for this session
	}
	payload, err := injector.RenderContextInjection(agent.ContextInjection{Text: entireTrailContextInjection()})
	if err != nil {
		logging.Warn(logCtx, "failed to render context injection",
			slog.String("error", err.Error()))
		return
	}
	if len(payload) == 0 {
		return
	}
	if _, err := os.Stdout.Write(payload); err != nil {
		logging.Warn(logCtx, "failed to write context injection",
			slog.String("error", err.Error()))
	}
}

