// trailsEnabledForRepo reports whether Entire trails are usable for this repo.
// Trails are a forge-backed feature, so the signal is the same guard the
// `entire trail` command uses: the origin remote resolves to a supported forge.
// Local and cheap (reads git remote config; no network), so it's safe to call
// on the hook hot path.
func trailsEnabledForRepo(ctx context.Context) bool {
	_, _, _, err := resolveTrailRemote(ctx)
	return err == nil
}

// emitContextInjection writes ag's native context-injection payload to stdout
// when ag injects at event.Type, trails are enabled for the repo, and this
// session has not been injected yet. Best-effort: an injection failure never
// fails the hook.
func emitContextInjection(ctx context.Context, ag agent.Agent, event *agent.Event) {
	injector, ok := agent.AsContextInjector(ag)
	if !ok || injector.InjectionEvent() != event.Type || event.SessionID == "" {
		return
	}
	// Only advertise trails where they're actually usable. Checked before the
	// claim so a session that enables trails later (e.g. adds an origin remote)
	// can still inject on a subsequent turn.
	if !trailsEnabledForRepo(ctx) {
		return
	}
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	claimed, err := strategy.ClaimContextInjection(ctx, event.SessionID)
	if err != nil {
		logging.Warn(logCtx, "failed to claim context injection marker",
			slog.String("error", err.Error()))
		return
	}
	if !claimed {
		return // already injected for this session
	}
	payload, err := injector.RenderContextInjection(agent.ContextInjection{Text: entireTrailContextInjection()})

