	t.Run("no origin remote", func(t *testing.T) {
		repoDir := t.TempDir()
		testutil.InitRepo(t, repoDir)
		t.Chdir(repoDir)
		if trailsEnabledForRepo(context.Background()) {
			t.Fatal("expected trails disabled without an origin remote")
		}
	})

	t.Run("supported forge origin", func(t *testing.T) {
		repoDir := t.TempDir()
		testutil.InitRepo(t, repoDir)
		addOrigin(t, repoDir, "git@github.com:acme/my-app.git")
		t.Chdir(repoDir)
		if !trailsEnabledForRepo(context.Background()) {
			t.Fatal("expected trails enabled for a github.com origin")
		}
