		addOrigin(t, repoDir, "git@gitlab.com:acme/my-app.git")
		t.Chdir(repoDir)
		if trailsEnabledForRepo(context.Background()) {
			t.Fatal("expected trails disabled for an unsupported forge")
		}
	})
}

